package com.greenocean.backend.listener.planning;
import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;
@Service @Transactional
public class ListenerQueueCoverage {
 private final ListenerSupportPolicy p;public ListenerQueueCoverage(ListenerSupportPolicy p){this.p=p;}
 public record Window(@NotNull UUID listenerId,@NotNull Instant startsAt,@NotNull Instant endsAt){}
 private void staff(UUID actor){if(!p.truth("SELECT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='ACTIVE' AND r.name IN('ADMIN','MODERATOR'))",actor))throw denied(403,"STAFF_REQUIRED","Current independent staffing authorization is required.");}
 public List<Map<String,Object>> mine(UUID actor){staff(actor);return p.db.queryForList("SELECT id,listener_id,starts_at,ends_at,revoked_at FROM listener_queue_coverage_windows WHERE ends_at>listener_support_now() ORDER BY starts_at,id LIMIT 100");}
 public UUID approve(UUID actor,Window in){p.liveLock();staff(actor);p.require("PLANNING");p.listener(in.listenerId());if(actor.equals(in.listenerId()))throw denied(403,"INDEPENDENT_REVIEW_REQUIRED","A listener cannot approve their own staffed queue coverage.");Instant now=p.now();if(!in.endsAt().isAfter(in.startsAt())||!in.endsAt().isAfter(now)||in.endsAt().isAfter(in.startsAt().plusSeconds(86400))||in.startsAt().isAfter(now.plus(Duration.ofDays(p.limits().horizonDays()))))throw new IllegalArgumentException("Choose an explicit staffing window up to 24 hours within the booking horizon");p.bound(actor,"COVERAGE",30);if(p.db.queryForObject("SELECT count(*) FROM listener_queue_coverage_windows WHERE listener_id=? AND revoked_at IS NULL AND ends_at>listener_support_now()",Integer.class,in.listenerId())>=14)throw denied(409,"COVERAGE_LIMIT","Review existing staffed windows before approving more.");UUID id=UUID.randomUUID();p.db.update("INSERT INTO listener_queue_coverage_windows(id,listener_id,starts_at,ends_at,approved_by) VALUES(?,?,?,?,?)",id,in.listenerId(),date(in.startsAt()),date(in.endsAt()),actor);return id;}
 public void revoke(UUID actor,UUID id){p.liveLock();staff(actor);if(p.db.update("UPDATE listener_queue_coverage_windows SET revoked_at=COALESCE(revoked_at,listener_support_now()) WHERE id=?",id)!=1)throw denied(404,"COVERAGE_NOT_FOUND","Staffing window was not found.");p.db.queryForList("SELECT reconcile_listener_queue()");}
}
